import type { TaskSeries } from '../features/recurring-tasks/index.ts';
import { expandRecurrenceDates } from '../features/recurring-tasks/index.ts';
import type { CampusLocation } from '../types.ts';
import { MAX_DAY_COUNT } from './scheduleRange.ts';
import { buildTaskLocation, defaultLocationDraft, draftFromLocation } from './taskLocationDraft.ts';
import type { LocationDraft } from './taskLocationDraft.ts';

/**
 * Pure draft/validation logic for the repeating-task form.
 *
 * The UI only ever stores the original TaskSeries. Occurrences are generated by
 * A's adapter on every run; `output.tasks` is display data and is never fed back
 * as input.
 */

export const ISO_WEEKDAYS: readonly { value: number; label: string; short: string }[] = [
  { value: 1, label: 'Monday', short: 'Mon' },
  { value: 2, label: 'Tuesday', short: 'Tue' },
  { value: 3, label: 'Wednesday', short: 'Wed' },
  { value: 4, label: 'Thursday', short: 'Thu' },
  { value: 5, label: 'Friday', short: 'Fri' },
  { value: 6, label: 'Saturday', short: 'Sat' },
  { value: 7, label: 'Sunday', short: 'Sun' },
];

export type SeriesFrequency = 'never' | 'daily' | 'weekly';

export interface SeriesDraft {
  title: string;
  durationMinutes: number;
  frequency: SeriesFrequency;
  interval: number;
  weekdays: number[];
  startDate: string;
  /** Empty string means no series end. */
  endDate: string;
  priority: '' | 'low' | 'medium' | 'high';
  courseCode: string;
  /** undefined semantics live in LocationDraft.choice === 'legacy'. */
  location: LocationDraft;
}

export const MAX_SERIES_TITLE = 80;
export const MAX_SERIES_DURATION = 600;

export function emptyDraft(startDate: string, locations: readonly CampusLocation[] = []): SeriesDraft {
  return {
    title: '',
    durationMinutes: 60,
    frequency: 'weekly',
    interval: 1,
    weekdays: [],
    startDate,
    endDate: '',
    priority: '',
    courseCode: '',
    location: defaultLocationDraft(locations),
  };
}

const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function validDate(value: string): boolean {
  if (!DATE_PATTERN.test(value)) return false;
  return new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value;
}

/** Null when the draft can be saved, otherwise the message to show. */
export function validateDraft(draft: SeriesDraft, locations: readonly CampusLocation[] = []): string | null {
  const title = draft.title.trim();
  if (!title) return 'Give the repeating task a title.';
  if (title.length > MAX_SERIES_TITLE) return `Keep the title under ${MAX_SERIES_TITLE} characters.`;
  if (!Number.isSafeInteger(draft.durationMinutes) || draft.durationMinutes <= 0 || draft.durationMinutes > MAX_SERIES_DURATION) {
    return `Duration must be a whole number of minutes between 1 and ${MAX_SERIES_DURATION}.`;
  }
  if (draft.frequency !== 'never') {
    if (!Number.isSafeInteger(draft.interval) || draft.interval < 1 || draft.interval > MAX_DAY_COUNT) {
      return `Repeat every ${MAX_DAY_COUNT} or fewer ${draft.frequency === 'daily' ? 'days' : 'weeks'}.`;
    }
  }
  if (draft.frequency === 'weekly') {
    if (!draft.weekdays.length) return 'Pick at least one weekday.';
    if (new Set(draft.weekdays).size !== draft.weekdays.length) return 'Pick each weekday once.';
    if (draft.weekdays.some((day) => !Number.isInteger(day) || day < 1 || day > 7)) {
      return 'Weekdays must be Monday through Sunday.';
    }
  }
  if (!validDate(draft.startDate)) return 'Pick a valid New York start date.';
  if (draft.endDate) {
    if (!validDate(draft.endDate)) return 'Pick a valid New York end date.';
    if (draft.endDate < draft.startDate) return 'The end date cannot be before the start date.';
  }
  const located = buildTaskLocation(draft.location, locations);
  if (!located.ok) return located.message;
  return null;
}

/** Builds the TaskSeries A's adapter expects. Never generates occurrences. */
export function draftToSeries(draft: SeriesDraft, id: string, locations: readonly CampusLocation[] = []): TaskSeries {
  const located = buildTaskLocation(draft.location, locations);
  if (!located.ok) throw new Error(located.message);
  const base = {
    id,
    title: draft.title.trim(),
    durationMinutes: draft.durationMinutes,
    startDate: draft.startDate,
    ...(draft.endDate ? { endDate: draft.endDate } : {}),
    ...(draft.priority ? { priority: draft.priority } : {}),
    ...(draft.courseCode.trim() ? { courseCode: draft.courseCode.trim() } : {}),
    ...(located.location ? { location: located.location } : {}),
  } as const;

  if (draft.frequency === 'daily') {
    return { ...base, rule: { frequency: 'daily', interval: draft.interval } };
  }
  if (draft.frequency === 'weekly') {
    return {
      ...base,
      rule: {
        frequency: 'weekly',
        interval: draft.interval,
        weekdays: [...draft.weekdays].sort((a, b) => a - b) as (1 | 2 | 3 | 4 | 5 | 6 | 7)[],
      },
    };
  }
  // 'never' is handled by the caller as a one-off task, never as a series.
  throw new Error('A never-repeating entry is a one-off task, not a series.');
}

export function seriesToDraft(series: TaskSeries, locations: readonly CampusLocation[] = []): SeriesDraft {
  return {
    title: series.title,
    durationMinutes: series.durationMinutes,
    frequency: series.rule.frequency,
    interval: series.rule.interval,
    weekdays: series.rule.frequency === 'weekly' ? [...series.rule.weekdays] : [],
    startDate: series.startDate,
    endDate: series.endDate ?? '',
    priority: series.priority ?? '',
    courseCode: series.courseCode ?? '',
    location: draftFromLocation(series.location, locations),
  };
}

/** True when the series being edited still exists in the current list. */
export function hasSeries(series: readonly TaskSeries[], id: string | null): boolean {
  return id !== null && series.some((item) => item.id === id);
}

/** How many occurrences a series produces inside the supplied calendar dates. */
export function occurrenceCount(series: TaskSeries, dates: readonly string[]): number {
  try {
    return expandRecurrenceDates(series, dates).length;
  } catch {
    return 0;
  }
}

export function describeRule(series: TaskSeries): string {
  const rule = series.rule;
  if (rule.frequency === 'daily') {
    return rule.interval === 1 ? 'Every day' : `Every ${rule.interval} days`;
  }
  const days = rule.weekdays
    .slice()
    .sort((a, b) => a - b)
    .map((day) => ISO_WEEKDAYS.find((entry) => entry.value === day)?.short ?? String(day))
    .join(', ');
  const cadence = rule.interval === 1 ? 'Every week' : `Every ${rule.interval} weeks`;
  return `${cadence} on ${days}`;
}
